CREATE DATABASE IF NOT EXISTS `db_administrasi_ujian` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `db_administrasi_ujian`;

SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS `tahun_ajaran`;
CREATE TABLE `tahun_ajaran` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `nama` VARCHAR(20) NOT NULL,
  `semester` ENUM('Ganjil', 'Genap') NOT NULL,
  `status_aktif` TINYINT(1) DEFAULT 0,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `tahun_ajaran` (`id`, `nama`, `semester`, `status_aktif`) VALUES (1, '2026/2027', 'Ganjil', True);

DROP TABLE IF EXISTS `kelas`;
CREATE TABLE `kelas` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `nama_kelas` VARCHAR(30) NOT NULL,
  `tingkat` VARCHAR(10) NOT NULL,
  `jurusan` VARCHAR(255) DEFAULT NULL,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

