DROP TABLE IF EXISTS `ujian`;
CREATE TABLE `ujian` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `tahun_ajaran_id` BIGINT NOT NULL,
  `nama_ujian` VARCHAR(150) NOT NULL,
  `jenis_ujian` VARCHAR(20) NOT NULL,
  `tgl_mulai` DATE NOT NULL,
  `tgl_selesai` DATE NOT NULL,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  CONSTRAINT `fk_ujian_tahun` FOREIGN KEY (`tahun_ajaran_id`) REFERENCES `tahun_ajaran` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `ujian` (`id`, `tahun_ajaran_id`, `nama_ujian`, `jenis_ujian`, `tgl_mulai`, `tgl_selesai`) VALUES (1, 1, 'SUMATIF AKHIR SEMESTER (SAS)', 'PAS', '2026-11-20', '2026-11-28');

DROP TABLE IF EXISTS `jadwal_ujian`;
CREATE TABLE `jadwal_ujian` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `ujian_id` BIGINT NOT NULL,
  `mapel_id` BIGINT NOT NULL,
  `tanggal` DATE NOT NULL,
  `jam_mulai` TIME NOT NULL,
  `jam_selesai` TIME NOT NULL,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  CONSTRAINT `fk_jadwal_ujian` FOREIGN KEY (`ujian_id`) REFERENCES `ujian` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_jadwal_mapel` FOREIGN KEY (`mapel_id`) REFERENCES `mapel` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

