DROP TABLE IF EXISTS `peserta_ujian`;
CREATE TABLE `peserta_ujian` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `ujian_id` BIGINT NOT NULL,
  `siswa_id` BIGINT NOT NULL,
  `no_peserta` VARCHAR(50) NOT NULL,
  `ruang_id` BIGINT DEFAULT NULL,
  `no_meja` INT DEFAULT NULL,
  `sesi` INT DEFAULT 1,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_ujian_siswa` (`ujian_id`, `siswa_id`),
  UNIQUE KEY `uq_ujian_no_peserta` (`ujian_id`, `no_peserta`),
  CONSTRAINT `fk_peserta_ujian` FOREIGN KEY (`ujian_id`) REFERENCES `ujian` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_peserta_siswa` FOREIGN KEY (`siswa_id`) REFERENCES `siswa` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_peserta_ruang` FOREIGN KEY (`ruang_id`) REFERENCES `ruang` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

