DROP TABLE IF EXISTS `nilai_ujian`;
CREATE TABLE `nilai_ujian` (
  `id` BIGINT NOT NULL AUTO_INCREMENT,
  `peserta_ujian_id` BIGINT NOT NULL,
  `jadwal_ujian_id` BIGINT NOT NULL,
  `nilai_pg` DECIMAL(5,2) DEFAULT 0.00,
  `nilai_esai` DECIMAL(5,2) DEFAULT 0.00,
  `nilai_akhir` DECIMAL(5,2) NOT NULL,
  `keterangan` ENUM('Hadir', 'Susulan', 'Tidak Hadir') DEFAULT 'Hadir',
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_peserta_jadwal` (`peserta_ujian_id`, `jadwal_ujian_id`),
  CONSTRAINT `fk_nilai_peserta` FOREIGN KEY (`peserta_ujian_id`) REFERENCES `peserta_ujian` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_nilai_jadwal` FOREIGN KEY (`jadwal_ujian_id`) REFERENCES `jadwal_ujian` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

SET FOREIGN_KEY_CHECKS = 1;
